INSERT INTO question_versions (id, question_id, version_number, stem, options, answer_spec, schema_version, explanation, status) VALUES
    ('2f000000-0000-4000-8000-040000000001', '2f000000-0000-4000-8000-030000000001', 1, 'Vertical farms grow their plants in soil kept in shallow trays.', '[{"optionKey":"TRUE","content":"TRUE","sortOrder":1},{"optionKey":"FALSE","content":"FALSE","sortOrder":2},{"optionKey":"NOT_GIVEN","content":"NOT GIVEN","sortOrder":3}]'::jsonb, '{"type":"CHOICE","correct":"FALSE"}'::jsonb, 1, 'Bước 1 · Hiểu câu hỏi
Câu hỏi nghĩa là: Các trang trại thẳng đứng trồng cây trong đất đặt trên khay nông.
Bước 2 · Tìm từ khóa và cách diễn đạt lại
- soil in shallow trays ~ stacked trays … with no soil
Bước 3 · Đối chiếu với bài đọc
Đoạn A: «Vertical farms grow salad leaves and herbs in stacked trays inside warehouses, with no soil and no sunlight»
Bài nói rõ không dùng đất («no soil») mà dùng nước chứa dưỡng chất, nên câu hỏi mâu thuẫn với bài.
Bước 4 · Đáp án
FALSE', 'PUBLISHED'),
    ('2f000000-0000-4000-8000-040000000002', '2f000000-0000-4000-8000-030000000002', 1, 'Growers claim that a vertical farm needs about one tenth of the water used in a field.', '[{"optionKey":"TRUE","content":"TRUE","sortOrder":1},{"optionKey":"FALSE","content":"FALSE","sortOrder":2},{"optionKey":"NOT_GIVEN","content":"NOT GIVEN","sortOrder":3}]'::jsonb, '{"type":"CHOICE","correct":"TRUE"}'::jsonb, 1, 'Bước 1 · Hiểu câu hỏi
Câu hỏi nghĩa là: Người trồng cho rằng trang trại thẳng đứng chỉ cần khoảng một phần mười lượng nước của ruộng.
Bước 2 · Tìm từ khóa và cách diễn đạt lại
- about one tenth ~ about a tenth
- water used in a field ~ the amount needed outdoors
Bước 3 · Đối chiếu với bài đọc
Đoạn B: «growers say they use about a tenth of the amount needed outdoors»
«A tenth» là một phần mười, «outdoors» là ngoài trời (ruộng), nên thông tin khớp.
Bước 4 · Đáp án
TRUE', 'PUBLISHED'),
    ('2f000000-0000-4000-8000-040000000003', '2f000000-0000-4000-8000-030000000003', 1, 'Vertical farms are cheaper to build than ordinary farms.', '[{"optionKey":"TRUE","content":"TRUE","sortOrder":1},{"optionKey":"FALSE","content":"FALSE","sortOrder":2},{"optionKey":"NOT_GIVEN","content":"NOT GIVEN","sortOrder":3}]'::jsonb, '{"type":"CHOICE","correct":"NOT_GIVEN"}'::jsonb, 1, 'Bước 1 · Hiểu câu hỏi
Câu hỏi nghĩa là: Trang trại thẳng đứng rẻ hơn để xây dựng so với trang trại thường.
Bước 2 · Tìm từ khóa và cách diễn đạt lại
- cheaper to build ~ (không có trong bài)
Bước 3 · Đối chiếu với bài đọc
Đoạn C: «Energy is the main cost»
Bài chỉ nói điện năng là chi phí chính, không so sánh chi phí xây dựng nên không thể kết luận.
Bước 4 · Đáp án
NOT GIVEN', 'PUBLISHED'),
    ('2f000000-0000-4000-8000-040000000004', '2f000000-0000-4000-8000-030000000004', 1, 'In a vertical farm, rows of coloured ______ replace the sun.', NULL, '{"type":"FILL","accepted":["lamps"]}'::jsonb, 1, 'Bước 1 · Hiểu câu hỏi
Câu hỏi nghĩa là: Trong trang trại thẳng đứng, các hàng ___ màu thay thế mặt trời.
Bước 2 · Tìm từ khóa và cách diễn đạt lại
- replace the sun ~ replace the sun
Bước 3 · Đối chiếu với bài đọc
Đoạn A: «rows of coloured lamps replace the sun»
Chỗ trống là danh từ số nhiều đứng sau «coloured», đó là «lamps» (đèn).
Bước 4 · Đáp án
lamps', 'PUBLISHED'),
    ('2f000000-0000-4000-8000-040000000005', '2f000000-0000-4000-8000-030000000005', 1, 'Because the water ______ in a closed system, much less of it is needed.', NULL, '{"type":"FILL","accepted":["circulates"]}'::jsonb, 1, 'Bước 1 · Hiểu câu hỏi
Câu hỏi nghĩa là: Vì nước ___ trong một hệ thống kín nên cần ít nước hơn nhiều.
Bước 2 · Tìm từ khóa và cách diễn đạt lại
- in a closed system ~ in a closed system
Bước 3 · Đối chiếu với bài đọc
Đoạn B: «Because the water circulates in a closed system»
Chỗ trống là động từ chia ở hiện tại số ít, bài dùng «circulates» (tuần hoàn).
Bước 4 · Đáp án
circulates', 'PUBLISHED'),
    ('2f000000-0000-4000-8000-040000000006', '2f000000-0000-4000-8000-030000000006', 1, 'The largest farms spend more on electricity than on ______.', NULL, '{"type":"FILL","accepted":["wages"]}'::jsonb, 1, 'Bước 1 · Hiểu câu hỏi
Câu hỏi nghĩa là: Các trang trại lớn nhất chi cho điện nhiều hơn chi cho ___.
Bước 2 · Tìm từ khóa và cách diễn đạt lại
- spend more on electricity than on ~ spend more on electricity than on
Bước 3 · Đối chiếu với bài đọc
Đoạn C: «the largest farms spend more on electricity than on wages»
Sau «than on» là danh từ được so sánh với điện, đó là «wages» (tiền lương).
Bước 4 · Đáp án
wages', 'PUBLISHED'),
    ('2f000000-0000-4000-8000-040000000007', '2f000000-0000-4000-8000-030000000007', 1, 'a reason why some people doubt that the method could feed the world', '[{"optionKey":"A","content":"Paragraph A","sortOrder":1},{"optionKey":"B","content":"Paragraph B","sortOrder":2},{"optionKey":"C","content":"Paragraph C","sortOrder":3},{"optionKey":"D","content":"Paragraph D","sortOrder":4}]'::jsonb, '{"type":"CHOICE","correct":"D"}'::jsonb, 1, 'Bước 1 · Hiểu câu hỏi
Câu hỏi nghĩa là: Một lý do khiến một số người nghi ngờ phương pháp này có thể nuôi sống thế giới.
Bước 2 · Tìm từ khóa và cách diễn đạt lại
- doubt ~ Critics reply
- feed the world ~ staple foods such as wheat could not be grown
Bước 3 · Đối chiếu với bài đọc
Đoạn D: «Critics reply that the crops are mostly lettuce and herbs, which have low value, and that staple foods such as wheat could not be grown in this way»
