    ('2f000000-0000-4000-8000-040000000055', '2f000000-0000-4000-8000-030000000055', 1, 'a way of helping customers who do not use banks', '[{"optionKey":"A","content":"Paragraph A","sortOrder":1},{"optionKey":"B","content":"Paragraph B","sortOrder":2},{"optionKey":"C","content":"Paragraph C","sortOrder":3},{"optionKey":"D","content":"Paragraph D","sortOrder":4}]'::jsonb, '{"type":"CHOICE","correct":"C"}'::jsonb, 1, 'Bước 1 · Hiểu câu hỏi
