    ('2f000000-0000-4000-8000-040000000056', '2f000000-0000-4000-8000-030000000056', 1, 'an example of how electricity allows children to learn', '[{"optionKey":"A","content":"Paragraph A","sortOrder":1},{"optionKey":"B","content":"Paragraph B","sortOrder":2},{"optionKey":"C","content":"Paragraph C","sortOrder":3},{"optionKey":"D","content":"Paragraph D","sortOrder":4}]'::jsonb, '{"type":"CHOICE","correct":"B"}'::jsonb, 1, 'Bước 1 · Hiểu câu hỏi
