    ('2f000000-0000-4000-8000-040000000059', '2f000000-0000-4000-8000-030000000059', 1, 'Paragraph D', '[{"optionKey":"A","content":"The most popular roof plants","sortOrder":1},{"optionKey":"B","content":"Why not every roof can be planted","sortOrder":2},{"optionKey":"C","content":"How plants cool the air above a roof","sortOrder":3},{"optionKey":"D","content":"A new use for old tar","sortOrder":4},{"optionKey":"E","content":"More benefits than a cooler city","sortOrder":5},{"optionKey":"F","content":"Training workers to build roofs","sortOrder":6}]'::jsonb, '{"type":"CHOICE","correct":"B"}'::jsonb, 1, 'Bước 1 · Hiểu câu hỏi
