    ('2f000000-0000-4000-8000-040000000060', '2f000000-0000-4000-8000-030000000060', 1, 'What is the urban heat island?', '[{"optionKey":"A","content":"A park in the centre of a city","sortOrder":1},{"optionKey":"B","content":"The warming of cities compared with nearby countryside","sortOrder":2},{"optionKey":"C","content":"A kind of cooling system","sortOrder":3}]'::jsonb, '{"type":"CHOICE","correct":"B"}'::jsonb, 1, 'Bước 1 · Hiểu câu hỏi
