    ('2f000000-0000-4000-8000-040000000062', '2f000000-0000-4000-8000-030000000062', 1, 'Why can many older buildings not have a green roof?', '[{"optionKey":"A","content":"They are too tall","sortOrder":1},{"optionKey":"B","content":"A green roof is too heavy without strengthening","sortOrder":2},{"optionKey":"C","content":"Plants do not grow on old tar","sortOrder":3}]'::jsonb, '{"type":"CHOICE","correct":"B"}'::jsonb, 1, 'Bước 1 · Hiểu câu hỏi
