    ('2f000000-0000-4000-8000-040000000064', '2f000000-0000-4000-8000-030000000064', 1, 'Some cities now give ______ to owners to help with the cost.', NULL, '{"type":"FILL","accepted":["grants"]}'::jsonb, 1, 'Bước 1 · Hiểu câu hỏi
