    ('2f000000-0000-4000-8000-040000000065', '2f000000-0000-4000-8000-030000000065', 1, 'The writer says that an idle wait can feel longer than a longer wait filled with activity.', '[{"optionKey":"YES","content":"YES","sortOrder":1},{"optionKey":"NO","content":"NO","sortOrder":2},{"optionKey":"NOT_GIVEN","content":"NOT GIVEN","sortOrder":3}]'::jsonb, '{"type":"CHOICE","correct":"YES"}'::jsonb, 1, 'Bước 1 · Hiểu câu hỏi
