    ('2f000000-0000-4000-8000-040000000066', '2f000000-0000-4000-8000-030000000066', 1, 'The writer thinks it is unsurprising that single lines are still rare.', '[{"optionKey":"YES","content":"YES","sortOrder":1},{"optionKey":"NO","content":"NO","sortOrder":2},{"optionKey":"NOT_GIVEN","content":"NOT GIVEN","sortOrder":3}]'::jsonb, '{"type":"CHOICE","correct":"NO"}'::jsonb, 1, 'Bước 1 · Hiểu câu hỏi
