    ('2f000000-0000-4000-8000-040000000067', '2f000000-0000-4000-8000-030000000067', 1, 'The writer states that theme parks earn more money from long queues.', '[{"optionKey":"YES","content":"YES","sortOrder":1},{"optionKey":"NO","content":"NO","sortOrder":2},{"optionKey":"NOT_GIVEN","content":"NOT GIVEN","sortOrder":3}]'::jsonb, '{"type":"CHOICE","correct":"NOT_GIVEN"}'::jsonb, 1, 'Bước 1 · Hiểu câu hỏi
