    ('2f000000-0000-4000-8000-040000000068', '2f000000-0000-4000-8000-030000000068', 1, 'What do psychologists say about time spent in a queue?', '[{"optionKey":"A","content":"It passes more slowly when we are idle","sortOrder":1},{"optionKey":"B","content":"It passes faster in the morning","sortOrder":2},{"optionKey":"C","content":"It stops when we watch a clock","sortOrder":3}]'::jsonb, '{"type":"CHOICE","correct":"A"}'::jsonb, 1, 'Bước 1 · Hiểu câu hỏi
