    ('2f000000-0000-4000-8000-040000000069', '2f000000-0000-4000-8000-030000000069', 1, 'Why is a single line judged fairer?', '[{"optionKey":"A","content":"It is shorter","sortOrder":1},{"optionKey":"B","content":"No one sees another customer served first","sortOrder":2},{"optionKey":"C","content":"It has more counters","sortOrder":3}]'::jsonb, '{"type":"CHOICE","correct":"B"}'::jsonb, 1, 'Bước 1 · Hiểu câu hỏi
