    ('2f000000-0000-4000-8000-040000000071', '2f000000-0000-4000-8000-030000000071', 1, 'A single line feeding several counters recorded fewer ______.', NULL, '{"type":"FILL","accepted":["complaints"]}'::jsonb, 1, 'Bước 1 · Hiểu câu hỏi
